      {...props}
    />
  );
}

"use client";

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Variants,
} from "framer-motion";
import { ChevronRight, MoreHorizontal } from "lucide-react";
import {
  type ComponentProps,
  type MouseEvent,
  type ReactNode,
  useMemo,
  useState,
} from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

export const breadcrumbVariants = tv({
  slots: {
    root: "w-full overflow-x-auto",
    list: "flex min-w-max items-center gap-1 rounded-2xl border border-border bg-card/80 p-1 shadow-xs backdrop-blur",
    item: "relative flex items-center",
    control: [
      "group relative inline-flex h-9 items-center gap-2 overflow-hidden rounded-xl px-3 text-sm outline-none",
      "text-muted-foreground transition-colors duration-200",
      "hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
      "data-[current=true]:text-foreground",
      "data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50",
    ],
    marker:
      "size-1.5 rounded-full bg-muted-foreground/40 transition-colors duration-200 group-data-[current=true]:bg-primary",
    label: "relative z-10 max-w-36 truncate",
    meta: "relative z-10 hidden text-xs text-muted-foreground/70 sm:inline",
    separator: "mx-0.5 text-muted-foreground/45",
    surface:
      "absolute inset-0 -z-10 rounded-xl border border-border bg-background shadow-xs",
  },
  variants: {
    size: {
      sm: {
        list: "rounded-xl p-0.5",
        control: "h-8 rounded-lg px-2.5 text-xs",
        surface: "rounded-lg",
      },
      md: {},
      lg: {
        list: "rounded-[20px] p-1.5",
        control: "h-10 rounded-2xl px-3.5",
        surface: "rounded-2xl",
      },
    },
    tone: {
      default: {},
      muted: {
        list: "bg-muted/35",
      },
      floating: {
        list: "bg-background/70 shadow-lg supports-[backdrop-filter]:bg-background/55",
      },
    },
  },
  defaultVariants: {
    size: "md",
    tone: "default",
  },
});

export type BreadcrumbItem = {
  label: string;
  href?: string;
  icon?: ReactNode;
  meta?: string;
  current?: boolean;
  disabled?: boolean;
};

export type BreadcrumbProps = Omit<ComponentProps<"nav">, "children"> &
  VariantProps<typeof breadcrumbVariants> & {
    items: BreadcrumbItem[];
    activeIndex?: number;
    maxVisible?: number;
    ariaLabel?: string;
    onNavigate?: (item: BreadcrumbItem, index: number) => void;
  };

type VisibleItem =
  | {
      kind: "item";
      item: BreadcrumbItem;
      index: number;
    }
  | {
      kind: "ellipsis";
      index: number;
    };

const smoothEase = [0.22, 1, 0.36, 1] as const;
const itemVariants: Variants = {
  hidden: { opacity: 0, y: 4, scale: 0.98 },
  visible: (index: number) => ({
    opacity: 1,
    y: 0,
    scale: 1,
    transition: {
      duration: 0.24,
      delay: index * 0.025,
      ease: smoothEase,
    },
  }),
};

function getVisibleItems(
  items: BreadcrumbItem[],
  maxVisible: number,
): VisibleItem[] {
  if (items.length <= maxVisible || maxVisible < 3) {
    return items.map((item, index) => ({ kind: "item", item, index }));
  }

  const tailCount = maxVisible - 2;
  const tail = items.slice(-tailCount).map((item, offset) => ({
    kind: "item" as const,
    item,
    index: items.length - tailCount + offset,
  }));

  return [
    { kind: "item", item: items[0], index: 0 },
    { kind: "ellipsis", index: 1 },
    ...tail,
  ];
}

export function Breadcrumb({
  items,
  activeIndex,
  maxVisible = 5,
  ariaLabel = "Breadcrumb",
  onNavigate,
  className,
  size,
  tone,
  ...props
}: BreadcrumbProps) {
  const styles = breadcrumbVariants({ size, tone });
  const shouldReduceMotion = useReducedMotion();
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
  const currentIndex =
    activeIndex ??
    items.findIndex((item) => item.current) ??
    Math.max(items.length - 1, 0);
  const safeCurrentIndex =
    currentIndex < 0 ? Math.max(items.length - 1, 0) : currentIndex;

  const visibleItems = useMemo(
    () => getVisibleItems(items, maxVisible),
    [items, maxVisible],
  );

  function handleNavigate(
    event: MouseEvent<HTMLAnchorElement | HTMLButtonElement>,
    item: BreadcrumbItem,
    index: number,
  ) {
    if (item.disabled) {
      event.preventDefault();
      return;
    }

    onNavigate?.(item, index);
  }

  return (
    <nav
      data-slot="breadcrumb"
      aria-label={ariaLabel}
      className={twMerge(styles.root(), className)}
      {...props}
    >
      <ol className={styles.list()}>
        {visibleItems.map((entry, visibleIndex) => {
          const isLast = visibleIndex === visibleItems.length - 1;

          if (entry.kind === "ellipsis") {
            return (
              <li
                key="ellipsis"
                className={styles.item()}
                aria-label="Collapsed breadcrumb items"
              >
                <span
                  className={twMerge(
                    styles.control(),
                    "cursor-default px-2 text-muted-foreground/70",
                  )}
                >
                  <MoreHorizontal className="size-4" aria-hidden="true" />
                </span>
                {!isLast ? (
                  <ChevronRight
                    className={twMerge(styles.separator(), "size-3.5")}
                    aria-hidden="true"
                  />
                ) : null}
              </li>
            );
          }

          const isCurrent = entry.index === safeCurrentIndex;
          const isHovered = hoveredIndex === entry.index;
          const showSurface = isCurrent || isHovered;
          const Control = entry.item.href ? motion.a : motion.button;

          return (
            <motion.li
              key={`${entry.item.label}-${entry.index}`}
              className={styles.item()}
              custom={visibleIndex}
              variants={itemVariants}
              initial={shouldReduceMotion ? false : "hidden"}
              animate="visible"
            >
              <Control
                href={entry.item.href}
                type={entry.item.href ? undefined : "button"}
                aria-current={isCurrent ? "page" : undefined}
                data-current={isCurrent}
                data-disabled={entry.item.disabled}
                className={styles.control()}
                onMouseEnter={() => setHoveredIndex(entry.index)}
                onMouseLeave={() => setHoveredIndex(null)}
                onFocus={() => setHoveredIndex(entry.index)}
                onBlur={() => setHoveredIndex(null)}
                onClick={(event) =>
                  handleNavigate(event, entry.item, entry.index)
                }
                whileTap={
                  shouldReduceMotion || entry.item.disabled
                    ? undefined
                    : { scale: 0.98 }
                }
                transition={{ duration: 0.16, ease: smoothEase }}
              >
                <AnimatePresence>
                  {showSurface ? (
                    <motion.span
                      layoutId="breadcrumb-surface"
                      className={styles.surface()}
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      exit={{ opacity: 0 }}
                      transition={{
                        type: "spring",
                        stiffness: 360,
                        damping: 34,
                        mass: 0.82,
                      }}
                      aria-hidden="true"
                    />
                  ) : null}
                </AnimatePresence>

                {entry.item.icon ? (
                  <span className="relative z-10 text-muted-foreground transition-colors duration-200 group-hover:text-foreground">
                    {entry.item.icon}
                  </span>
                ) : (
                  <span className={styles.marker()} aria-hidden="true" />
                )}
                <span className={styles.label()}>{entry.item.label}</span>
                {entry.item.meta ? (
                  <span className={styles.meta()}>{entry.item.meta}</span>
                ) : null}
              </Control>

              {!isLast ? (
                <motion.span
                  className={styles.separator()}
                  animate={
                    shouldReduceMotion
                      ? undefined
                      : {
                          x: isHovered ? 1 : 0,
                          opacity: isHovered ? 0.85 : 0.45,
                        }
                  }
                  transition={{ duration: 0.18, ease: smoothEase }}
                  aria-hidden="true"
                >
                  <ChevronRight className="size-3.5" />
                </motion.span>
              ) : null}
            </motion.li>
          );
        })}
      </ol>
    </nav>
  );
}

import type { ComponentProps } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

export const dividerVariants = tv({
  base: "shrink-0 border-border",

  variants: {
    orientation: {
      horizontal: "w-full border-t",
      vertical: "h-full border-l",
    },

    variant: {
      solid: "",
      dashed: "border-dashed",
      dotted: "border-dotted",
    },

    color: {
      default: "border-border",
    },

    size: {
      sm: "border",
      md: "border-2",
      lg: "border-[3px]",
    },
  },

  defaultVariants: {
    orientation: "horizontal",
    variant: "solid",
    color: "default",
    size: "sm",
  },
});

export type DividerProps = ComponentProps<"div"> &
  VariantProps<typeof dividerVariants>;

export function Divider({
  className,
  orientation = "horizontal",
  variant,
  color,
  size,
  ...props
}: DividerProps) {
  const classes = twMerge(
    dividerVariants({ orientation, variant, color, size }),
    className,
  );

  if (orientation === "vertical") {
    return (
      <div
        data-slot="divider"
        data-orientation="vertical"
        className={classes}
        aria-hidden
        {...props}
      />
    );
  }

  return (
    <hr
      data-slot="divider"
      data-orientation="horizontal"
      className={classes}
      aria-hidden
      {...(props as ComponentProps<"hr">)}
    />
  );
}

"use client";

import { AnimatePresence, type HTMLMotionProps, motion } from "framer-motion";
import { ChevronDown } from "lucide-react";
import * as React from "react";

import { cn } from "@/lib/utils";

type AccordionContextType = {
  openItems: string[];
  toggleItem: (value: string) => void;
};

const AccordionContext = React.createContext<AccordionContextType | null>(null);

export interface AccordionProps extends React.ComponentProps<"div"> {
  children: React.ReactNode;
}

export function Accordion({ children, className, ...props }: AccordionProps) {
  const [openItems, setOpenItems] = React.useState<string[]>([]);

  const toggleItem = React.useCallback((value: string) => {
    setOpenItems((prev) =>
      prev.includes(value) ? prev.filter((i) => i !== value) : [...prev, value],
    );
  }, []);

  const value = React.useMemo(
    () => ({ openItems, toggleItem }),
    [openItems, toggleItem],
  );

  return (
    <AccordionContext.Provider value={value}>
      <div
        data-slot="accordion"
        className={cn("w-full space-y-2", className)}
        {...props}
      >
        {children}
      </div>
    </AccordionContext.Provider>
  );
}

export interface AccordionItemProps extends HTMLMotionProps<"div"> {
  value: string;
  children: React.ReactNode;
}

export function AccordionItem({
  value: _value,
  children,
  className,
  ...props
}: AccordionItemProps) {
  return (
    <motion.div
      layout
      data-slot="accordion-item"
      className={cn(
        "overflow-hidden rounded-xl border border-border bg-card",
        className,
      )}
      {...props}
    >
      {children}
    </motion.div>
  );
}

export interface AccordionTriggerProps extends React.ComponentProps<"button"> {
  value: string;
  children: React.ReactNode;
}

export function AccordionTrigger({
  value,
  children,
  className,
  ...props
}: AccordionTriggerProps) {
  const context = React.useContext(AccordionContext);
  if (!context)
    throw new Error("AccordionTrigger must be used within Accordion");

  const isOpen = context.openItems.includes(value);

  const handleKeyDown = React.useCallback(
    (e: React.KeyboardEvent<HTMLButtonElement>) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        context.toggleItem(value);
      }
    },
    [context, value],
  );

  return (
    <button
      type="button"
      data-slot="accordion-trigger"
      data-state={isOpen ? "open" : "closed"}
      aria-expanded={isOpen}
      onClick={() => context.toggleItem(value)}
      onKeyDown={handleKeyDown}
      className={cn(
        "flex w-full items-center justify-between px-4 py-2 text-left outline-none transition-colors",
        "focus-visible:ring-2 focus-visible:ring-ring",
        isOpen ? "bg-accent" : "hover:bg-accent",
        className,
      )}
      {...props}
    >
      <div className="flex flex-col">
        <span className="text-sm font-medium text-foreground">{children}</span>
      </div>
      <motion.div
        animate={{ rotate: isOpen ? 180 : 0 }}
        transition={{ type: "spring", stiffness: 260, damping: 20 }}
      >
        <ChevronDown className="size-4 text-muted-foreground" aria-hidden />
      </motion.div>
    </button>
  );
}

export interface AccordionContentProps extends HTMLMotionProps<"div"> {
  value: string;
  children: React.ReactNode;
}

export function AccordionContent({
  value,
  children,
  className,
  ...props
}: AccordionContentProps) {
  const context = React.useContext(AccordionContext);
  if (!context)
    throw new Error("AccordionContent must be used within Accordion");

  const isOpen = context.openItems.includes(value);

  return (
    <AnimatePresence initial={false}>
      {isOpen && (
        <motion.div
          layout
          data-slot="accordion-content"
          initial={{ height: 0, opacity: 0 }}
          animate={{ height: "auto", opacity: 1 }}
          exit={{ height: 0, opacity: 0 }}
          transition={{ type: "spring", stiffness: 260, damping: 25 }}
          className={cn("overflow-hidden", className)}
          {...props}
        >
          <div className="bg-accent px-4 pb-4 pt-2 text-sm leading-relaxed text-muted-foreground">
            {children}
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

"use client";

import type { ComponentProps, ReactNode } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

import { Button } from "@/components/matos-ui/button";

export const actionBarVariants = tv({
  base: [
    "fixed z-50 flex items-center gap-3 border shadow-lg",
    "backdrop-blur-sm supports-[backdrop-filter]:bg-background/20",
  ],
  variants: {
    placement: {
      bottomCenter: "bottom-6 left-1/2 -translate-x-1/2",
      bottomRight: "bottom-6 right-6 left-auto translate-x-0",
      bottomLeft: "bottom-6 left-6 right-auto translate-x-0",
    },
    tone: {
      default: "border-border bg-surface-raised",
      destructive: "border-destructive/50 bg-destructive/10",
      success: "border-green-500/30 bg-green-500/10",
      warning: "border-yellow-500/30 bg-yellow-500/10",
    },
    size: {
      sm: "rounded-lg px-3 py-2",
      md: "rounded-xl px-4 py-3",
    },
  },
  defaultVariants: {
    placement: "bottomCenter",
    tone: "default",
    size: "md",
  },
});

export interface ActionBarActions {
  onConfirm: () => void;
  onCancel: () => void;
  isLoading?: boolean;
}

type ActionBarPropsBase = ComponentProps<"div"> &
  VariantProps<typeof actionBarVariants> & {
    subject?: string;
    title?: string;
    description?: string;
    icon?: ReactNode;
    ariaLabel?: string;
    cancelLabel?: string;
    confirmLabel?: string;
    confirmLabelLoading?: string;
  };

type ActionBarPropsWithActions = ActionBarPropsBase & {
  actions: ActionBarActions;
  onConfirm?: never;
  onCancel?: never;
  isLoading?: never;
};

type ActionBarPropsLegacy = ActionBarPropsBase & {
  actions?: undefined;
  onConfirm: () => void;
  onCancel: () => void;
  isLoading?: boolean;
};

export type ActionBarProps = ActionBarPropsWithActions | ActionBarPropsLegacy;

export function ActionBar(props: ActionBarProps) {
  const {
    subject,
    title,
    description,
    icon,

    ariaLabel = "Confirmar ação",
    cancelLabel = "Cancelar",
    confirmLabel = "Confirmar",
    confirmLabelLoading = "Processando…",
    className,
    placement,
    tone,
    size,
    ...rest
  } = props;

  const actions: ActionBarActions =
    "actions" in props && props.actions
      ? props.actions
      : {
          onConfirm: props.onConfirm,
          onCancel: props.onCancel,
          isLoading: props.isLoading,
        };

  const isLoading = actions.isLoading ?? false;

  return (
    <>
      {/* 🔥 BACKDROP COM BLUR */}
      <div className="" aria-hidden />

      <div
        data-slot="action-bar"
        role="dialog"
        aria-label={ariaLabel}
        data-loading={isLoading ? "" : undefined}
        className={twMerge(
          actionBarVariants({ placement, tone, size }),
          className,
        )}
        {...rest}
      >
        <div className="flex items-center gap-2 text-sm font-medium text-foreground">
          {icon}

          <div className="flex flex-col">
            <span>
              {title ??
                (subject
                  ? `Confirmar ação em "${subject}"?`
                  : "Tem certeza que deseja continuar?")}
            </span>

            {description && (
              <span className="text-xs text-muted-foreground">
                {description}
              </span>
            )}
          </div>
        </div>

        <div className="flex gap-2">
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={actions.onCancel}
            disabled={isLoading}
          >
            {cancelLabel}
          </Button>

          <Button
            type="button"
            variant={tone === "destructive" ? "destructive" : "default"}
            size="sm"
            onClick={actions.onConfirm}
            disabled={isLoading}
          >
            {isLoading ? confirmLabelLoading : confirmLabel}
          </Button>
        </div>
      </div>
    </>
  );
}

"use client";

import {
  AnimatePresence,
  type HTMLMotionProps,
  motion,
  useReducedMotion,
  type Variants,
} from "framer-motion";
import { MoreHorizontal, X } from "lucide-react";
import {
  type ComponentProps,
  createContext,
  type ReactNode,
  useContext,
} from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

export const detailPanelVariants = tv({
  base: [
    "w-full max-w-[420px] overflow-hidden rounded-2xl border border-border",
    "bg-secondary text-foreground shadow-xl",
  ],
});

const fadeUp = (delay = 0) =>
  ({
    initial: { opacity: 0, y: 10 },
    animate: { opacity: 1, y: 0 },
    transition: {
      duration: 0.35,
      ease: [0.25, 0.46, 0.45, 0.94] as const,
      delay,
    },
  }) as const;

const listVariants: Variants = {
  hidden: {},
  show: {
    transition: { staggerChildren: 0.055 },
  },
};

const rowItemVariants: Variants = {
  hidden: { opacity: 0, x: -6 },
  show: {
    opacity: 1,
    x: 0,
    transition: { duration: 0.3, ease: "easeOut" },
  },
};

type DetailPanelContextValue = {
  onClose?: () => void;
};

const DetailPanelContext = createContext<DetailPanelContextValue | null>(null);

function useDetailPanelContext() {
  return useContext(DetailPanelContext);
}

export type DetailPanelProps = Omit<HTMLMotionProps<"div">, "children"> &
  VariantProps<typeof detailPanelVariants> & {
    open?: boolean;
    onClose?: () => void;
    children?: ReactNode;
  };

function DetailPanel({
  className,
  open = true,
  onClose,
  children,
  ...motionProps
}: DetailPanelProps) {
  const shouldReduceMotion = useReducedMotion();

  const panelVariants: Variants = {
    hidden: shouldReduceMotion
      ? { opacity: 0 }
      : { opacity: 0, scale: 0.96, y: 8 },
    visible: {
      opacity: 1,
      scale: 1,
      y: 0,
      transition: {
        duration: 0.4,
        ease: [0.16, 1, 0.3, 1] as const,
      },
    },
    exit: shouldReduceMotion
      ? { opacity: 0 }
      : {
          opacity: 0,
          scale: 0.97,
          y: 4,
          transition: { duration: 0.2, ease: "easeIn" },
        },
  };

  return (
    <AnimatePresence>
      {open ? (
        <motion.div
          key="detail-panel"
          variants={panelVariants}
          initial="hidden"
          animate="visible"
          exit="exit"
          data-slot="detail-panel"
          className={twMerge(detailPanelVariants(), className)}
          {...motionProps}
        >
          <DetailPanelContext.Provider value={{ onClose }}>
            {children}
          </DetailPanelContext.Provider>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}

