      },
      false: {},
    },
  },
  compoundVariants: [
    {
      variant: "default",
      isDragging: true,
      class: {
        root: "border-primary/45 bg-primary/5",
        glow: "opacity-100",
        icon: "border-primary/30 bg-primary/10 text-primary",
      },
    },
    {
      variant: "outline",
      isDragging: true,
      class: {
        root: "border-primary/45 bg-primary/5",
        glow: "opacity-100",
        icon: "border-primary/30 bg-primary/10 text-primary",
      },
    },
    {
      variant: "ghost",
      isDragging: true,
      class: {
        root: "bg-primary/5",
        glow: "opacity-100",
        icon: "bg-primary/10 text-primary",
      },
    },
  ],
  defaultVariants: {
    variant: "default",
    size: "md",
    isDragging: false,
    disabled: false,
  },
});

export interface FileUploadFile {
  file: File;
  id: string;
  error?: string;
}

export type FileUploadProps = Omit<
  HTMLMotionProps<"div">,
  "children" | "onChange"
> &
  VariantProps<typeof fileUploadVariants> & {
    accept?: string;
    multiple?: boolean;
    maxSize?: number;
    maxFiles?: number;
    files?: FileUploadFile[];
    onFilesChange?: (files: FileUploadFile[]) => void;
    title?: string;
    description?: string;
    disabled?: boolean;
  };

const smoothEase = [0.22, 1, 0.36, 1] as const;
const listSpring = {
  type: "spring",
  stiffness: 320,
  damping: 30,
  mass: 0.82,
} as const;

function generateId() {
  return Math.random().toString(36).slice(2, 10);
}

function formatFileSize(bytes: number): string {
  if (bytes === 0) {
    return "0 B";
  }

  const units = ["B", "KB", "MB", "GB"];
  const i = Math.floor(Math.log(bytes) / Math.log(1024));

  return `${(bytes / 1024 ** i).toFixed(i === 0 ? 0 : 1)} ${units[i]}`;
}

export function FileUpload({
  className,
  variant = "default",
  size = "md",
  accept,
  multiple = false,
  maxSize,
  maxFiles,
  files: controlledFiles,
  onFilesChange,
  title: titleText,
  description: descriptionText,
  disabled = false,
  ...props
}: FileUploadProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const [dragging, setDragging] = useState(false);
  const [internalFiles, setInternalFiles] = useState<FileUploadFile[]>([]);

  const isControlled = controlledFiles !== undefined;
  const files = isControlled ? controlledFiles : internalFiles;

  const updateFiles = useCallback(
    (next: FileUploadFile[]) => {
      if (!isControlled) {
        setInternalFiles(next);
      }

      onFilesChange?.(next);
    },
    [isControlled, onFilesChange],
  );

  const validateFile = useCallback(
    (file: File): string | undefined => {
      if (maxSize && file.size > maxSize) {
        return `Arquivo excede ${formatFileSize(maxSize)}`;
      }

      return undefined;
    },
    [maxSize],
  );

  const addFiles = useCallback(
    (incoming: File[]) => {
      if (disabled) {
        return;
      }

      const newEntries: FileUploadFile[] = incoming.map((file) => ({
        file,
        id: generateId(),
        error: validateFile(file),
      }));

      let nextFiles: FileUploadFile[];

      if (multiple) {
        nextFiles = [...files, ...newEntries];

        if (maxFiles && nextFiles.length > maxFiles) {
          nextFiles = nextFiles.slice(0, maxFiles);
        }
      } else {
        nextFiles = newEntries.slice(0, 1);
      }

      updateFiles(nextFiles);
    },
    [disabled, files, multiple, maxFiles, validateFile, updateFiles],
  );

  const removeFile = useCallback(
    (id: string) => {
      updateFiles(files.filter((file) => file.id !== id));
    },
    [files, updateFiles],
  );

  const handleDragOver = useCallback(
    (event: DragEvent<HTMLDivElement>) => {
      event.preventDefault();
      event.stopPropagation();

      if (!disabled) {
        setDragging(true);
      }
    },
    [disabled],
  );

  const handleDragLeave = useCallback((event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    setDragging(false);
  }, []);

  const handleDrop = useCallback(
    (event: DragEvent<HTMLDivElement>) => {
      event.preventDefault();
      event.stopPropagation();
      setDragging(false);

      if (event.dataTransfer?.files) {
        addFiles(Array.from(event.dataTransfer.files));
      }
    },
    [addFiles],
  );

  const handleChange = useCallback(
    (event: ChangeEvent<HTMLInputElement>) => {
      if (event.target.files) {
        addFiles(Array.from(event.target.files));
      }

      event.target.value = "";
    },
    [addFiles],
  );

  const handleClick = useCallback(() => {
    if (!disabled) {
      inputRef.current?.click();
    }
  }, [disabled]);

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        handleClick();
      }
    },
    [handleClick],
  );

  const styles = fileUploadVariants({
    variant,
    size,
    isDragging: dragging,
    disabled,
  });

  const defaultTitle = dragging
    ? "Solte os arquivos aqui"
    : "Arraste seus arquivos";

  const defaultDescription = multiple
    ? "ou clique para selecionar varios arquivos"
    : "ou clique para selecionar um arquivo";

  return (
    <div data-slot="file-upload" className="w-full">
      <motion.div
        role="button"
        tabIndex={disabled ? -1 : 0}
        aria-label="Area de upload de arquivos"
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        className={twMerge(styles.root(), className)}
        animate={
          shouldReduceMotion
            ? undefined
            : {
                scale: dragging ? 1.01 : 1,
                y: dragging ? -2 : 0,
                boxShadow: dragging
                  ? "0 18px 42px color-mix(in oklch, var(--primary) 13%, transparent)"
                  : "0 1px 2px color-mix(in oklch, var(--foreground) 8%, transparent)",
              }
        }
        whileTap={shouldReduceMotion || disabled ? undefined : { scale: 0.995 }}
        transition={{ duration: 0.24, ease: smoothEase }}
        {...props}
      >
        <span className={styles.glow()} aria-hidden="true" />

        <motion.span
          className={styles.icon()}
          animate={
            shouldReduceMotion
              ? undefined
              : {
                  y: dragging ? -1 : 0,
                  scale: dragging ? 1.04 : 1,
                }
          }
          transition={{ duration: 0.28, ease: smoothEase }}
        >
          <Upload aria-hidden="true" />
        </motion.span>

        <div className="flex flex-col gap-1">
          <span className={styles.title()}>{titleText ?? defaultTitle}</span>
          <span className={styles.description()}>
            {descriptionText ?? defaultDescription}
          </span>
        </div>

        {accept && (
          <span className="rounded-full border border-border bg-background px-2 py-0.5 text-[10px] text-muted-foreground/70">
            {accept}
          </span>
        )}
      </motion.div>

      <input
        ref={inputRef}
        type="file"
        className="sr-only"
        accept={accept}
        multiple={multiple}
        onChange={handleChange}
        tabIndex={-1}
        aria-hidden="true"
      />

      <AnimatePresence initial={false}>
        {files.length > 0 && (
          <motion.ul
            className={styles.fileList()}
            data-slot="file-upload-list"
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 4 }}
            animate={shouldReduceMotion ? { opacity: 1 } : { opacity: 1, y: 0 }}
            exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
            transition={{ duration: 0.22, ease: smoothEase }}
          >
            <AnimatePresence initial={false}>
              {files.map((entry) => (
                <motion.li
                  key={entry.id}
                  layout
                  className={styles.fileItem()}
                  initial={
                    shouldReduceMotion
                      ? { opacity: 0 }
                      : { opacity: 0, y: 8, scale: 0.985 }
                  }
                  animate={
                    shouldReduceMotion
                      ? { opacity: 1 }
                      : { opacity: 1, y: 0, scale: 1 }
                  }
                  exit={
                    shouldReduceMotion
                      ? { opacity: 0 }
                      : { opacity: 0, x: 10, scale: 0.985 }
                  }
                  transition={listSpring}
                >
                  <FileText
                    className="size-4 shrink-0 text-muted-foreground"
                    aria-hidden="true"
                  />

                  <span className={styles.fileName()}>{entry.file.name}</span>

                  <span className={styles.fileSize()}>
                    {formatFileSize(entry.file.size)}
                  </span>

                  {entry.error && (
                    <span className={styles.errorText()}>
                      <AlertCircle className="size-3.5" aria-hidden="true" />
                      {entry.error}
                    </span>
                  )}

                  <button
                    type="button"
                    aria-label={`Remover ${entry.file.name}`}
                    className={styles.removeButton()}
                    onClick={(event) => {
                      event.stopPropagation();
                      removeFile(entry.id);
                    }}
                  >
                    <X className="size-3.5" aria-hidden="true" />
                  </button>
                </motion.li>
              ))}
            </AnimatePresence>
          </motion.ul>
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import {
  AnimatePresence,
  motion,
  type PanInfo,
  type Variants,
} from "framer-motion";
import { X } from "lucide-react";
import {
  type ComponentProps,
  createContext,
  type ReactNode,
  useCallback,
  useContext,
  useMemo,
  useRef,
  useState,
} from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

export const notificationStackVariants = tv({
  base: ["relative flex flex-col items-center"],
  variants: {
    size: {
      sm: "w-[300px]",
      md: "w-[360px]",
      lg: "w-[420px]",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export const notificationCardVariants = tv({
  base: [
    "w-full overflow-hidden rounded-[16px] border border-border",
    "bg-secondary text-foreground shadow-lg",
  ],
});

export type NotificationData = {
  id: string;
  app?: string;
  title: string;
  description?: string;
  avatar?: ReactNode;
  timestamp?: string;
  action?: {
    label: string;
    onClick: () => void;
  };
};

type NotificationContextValue = {
  notifications: NotificationData[];
  add: (notification: Omit<NotificationData, "id">) => string;
  dismiss: (id: string) => void;
  dismissAll: () => void;
};

const NotificationContext = createContext<NotificationContextValue | null>(
  null,
);

export function useNotificationStack() {
  const ctx = useContext(NotificationContext);
  if (!ctx) {
    throw new Error(
      "useNotificationStack must be used within a NotificationStackProvider",
    );
  }
  return ctx;
}

export type NotificationStackProviderProps = {
  children: ReactNode;
};

export function NotificationStackProvider({
  children,
}: NotificationStackProviderProps) {
  const [notifications, setNotifications] = useState<NotificationData[]>([]);
  const counterRef = useRef(0);

  const add = useCallback((notification: Omit<NotificationData, "id">) => {
    counterRef.current += 1;
    const id = `notification-${counterRef.current}-${Date.now()}`;
    const newNotification: NotificationData = { ...notification, id };
    setNotifications((prev) => [...prev, newNotification]);
    return id;
  }, []);

  const dismiss = useCallback((id: string) => {
    setNotifications((prev) => prev.filter((n) => n.id !== id));
  }, []);

  const dismissAll = useCallback(() => {
    setNotifications([]);
  }, []);

  const value = useMemo(
    () => ({ notifications, add, dismiss, dismissAll }),
    [notifications, add, dismiss, dismissAll],
  );

  return (
    <NotificationContext.Provider value={value}>
      {children}
    </NotificationContext.Provider>
  );
}

const cardVariants: Variants = {
  initial: { opacity: 0, y: -30, scale: 0.96 },
  animate: {
    opacity: 1,
    y: 0,
    scale: 1,
    transition: {
      type: "spring",
      stiffness: 380,
      damping: 26,
      mass: 0.8,
    },
  },
  exit: {
    opacity: 0,
    y: -50,
    scale: 0.93,
    transition: {
      duration: 0.25,
      ease: [0.36, 0, 0.66, -0.56],
    },
  },
};

const stackLayerVariants: Variants = {
  initial: { opacity: 0, scale: 0.9, y: 0 },
  animate: (i: number) => ({
    opacity: 1,
    scaleX: 1 - i * 0.04,
    scaleY: 1,
    y: i * 5,
    transition: {
      type: "spring",
      stiffness: 300,
      damping: 24,
      delay: i * 0.05,
    },
  }),
  exit: {
    opacity: 0,
    scale: 0.9,
    transition: { duration: 0.2 },
  },
};

export type NotificationStackProps = ComponentProps<"div"> &
  VariantProps<typeof notificationStackVariants> & {
    notifications: NotificationData[];
    onDismiss?: (id: string) => void;
    maxStackLayers?: number;
  };

export function NotificationStack({
  className,
  size,
  notifications,
  onDismiss,
  maxStackLayers = 3,
  ...props
}: NotificationStackProps) {
  const topNotification = notifications[notifications.length - 1];
  const stackCount = Math.min(notifications.length - 1, maxStackLayers);
  const remainingCount = notifications.length - 1;

  function handleDragEnd(_: unknown, info: PanInfo) {
    if (!topNotification) return;
    if (Math.abs(info.offset.y) > 80 || Math.abs(info.offset.x) > 120) {
      onDismiss?.(topNotification.id);
    }
  }

  return (
    <div
      data-slot="notification-stack"
      className={twMerge(notificationStackVariants({ size }), className)}
      {...props}
    >
      <div
        className="relative w-full"
        style={{ paddingBottom: stackCount * 5 }}
      >
        <AnimatePresence>
          {Array.from({ length: stackCount }).map((_, i) => {
            const layerIndex = stackCount - i;
            return (
              <motion.div
                key={`stack-layer-${layerIndex}`}
                custom={layerIndex}
                variants={stackLayerVariants}
                initial="initial"
                animate="animate"
                exit="exit"
                className="absolute inset-x-0 bottom-0 top-0 z-0 origin-bottom"
                style={{ zIndex: i }}
              >
                <div
                  className={twMerge(
                    notificationCardVariants(),
                    "h-full w-full",
                  )}
                  style={{ opacity: 0.3 + i * 0.2 }}
                />
              </motion.div>
            );
          })}
        </AnimatePresence>

        <AnimatePresence mode="popLayout">
          {topNotification ? (
            <motion.div
              key={topNotification.id}
              variants={cardVariants}
              initial="initial"
              animate="animate"
              exit="exit"
              drag
              dragConstraints={{ left: 0, right: 0, top: 0, bottom: 0 }}
              dragElastic={0.5}
              onDragEnd={handleDragEnd}
              className="relative cursor-grab active:cursor-grabbing"
              style={{ zIndex: stackCount + 1 }}
            >
              <div className={notificationCardVariants()}>
                <div
                  className={twMerge(
                    "flex items-center gap-2.5 overflow-hidden rounded-xl bg-card px-3 py-2 mx-1 mt-1",
                    remainingCount === 0 && "mb-1",
                  )}
                >
                  {topNotification.avatar && (
                    <motion.div
                      initial={{ scale: 0, opacity: 0 }}
                      animate={{ scale: 1, opacity: 1 }}
                      transition={{
                        type: "spring",
                        stiffness: 400,
                        damping: 20,
                        delay: 0.12,
                      }}
                      className="flex size-7 shrink-0 items-center justify-center overflow-hidden rounded-full bg-muted"
                    >
                      {topNotification.avatar}
                    </motion.div>
                  )}

                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-1.5">
                      {topNotification.app && (
                        <motion.span
                          initial={{ opacity: 0 }}
                          animate={{ opacity: 1 }}
                          transition={{ delay: 0.1 }}
                          className="text-[10px] font-medium uppercase tracking-widest text-muted-foreground"
                        >
                          {topNotification.app}
                        </motion.span>
                      )}
                      <motion.p
                        initial={{ opacity: 0, x: -6 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: 0.08, duration: 0.25 }}
                        className="truncate text-sm font-semibold leading-tight"
                      >
                        {topNotification.title}
                      </motion.p>
                    </div>

                    {topNotification.description && (
                      <motion.p
                        initial={{ opacity: 0, x: -6 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: 0.14, duration: 0.25 }}
                        className="truncate text-xs leading-snug text-muted-foreground"
                      >
                        {topNotification.description}
                      </motion.p>
                    )}
                  </div>

                  <div className="flex shrink-0 items-center gap-1.5">
                    {topNotification.timestamp && (
                      <motion.span
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        transition={{ delay: 0.15 }}
                        className="text-[10px] text-muted-foreground"
                      >
                        {topNotification.timestamp}
                      </motion.span>
                    )}

                    {topNotification.action && (
                      <motion.button
                        type="button"
                        initial={{ opacity: 0, y: 4 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: 0.22 }}
                        whileHover={{ scale: 1.02 }}
                        whileTap={{ scale: 0.97 }}
                        onClick={topNotification.action.onClick}
                        className="rounded-md bg-primary px-2 py-0.5 text-[11px] font-medium text-primary-foreground transition-colors hover:bg-primary/90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                      >
                        {topNotification.action.label}
                      </motion.button>
                    )}

                    <motion.button
                      type="button"
                      whileHover={{ scale: 1.15 }}
                      whileTap={{ scale: 0.85 }}
                      onClick={() => onDismiss?.(topNotification.id)}
                      aria-label="Dispensar notificação"
                      className="flex size-5 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      <X className="size-3" strokeWidth={2} />
                    </motion.button>
                  </div>
                </div>

                {remainingCount > 0 && (
                  <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ delay: 0.25 }}
                    className="flex items-center px-3 pt-1.5 pb-2"
                  >
                    <span className="text-[11px] text-muted-foreground/80">
                      {remainingCount} more notification
                      {remainingCount > 1 ? "s" : ""}
                    </span>
                  </motion.div>
                )}
              </div>
            </motion.div>
          ) : null}
        </AnimatePresence>
      </div>
    </div>
  );
}

"use client";

import { motion, useMotionValue, useSpring, useTransform } from "framer-motion";
import { ArrowDown, ArrowUp, Minus } from "lucide-react";
import { type ComponentProps, type ReactNode, useEffect } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

export const metricCardVariants = tv({
  base: [
    "w-full overflow-hidden rounded-[20px] border border-border",
    "bg-secondary text-foreground",
  ],
  variants: {
    size: {
      sm: "max-w-[280px]",
      md: "max-w-[340px]",
      lg: "max-w-[400px]",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

const fadeUp = (delay = 0) =>
  ({
    initial: { opacity: 0, y: 8 },
    animate: { opacity: 1, y: 0 },
    transition: {
      duration: 0.4,
      ease: [0.25, 0.46, 0.45, 0.94] as const,
      delay,
    },
  }) as const;

export type MetricCardProps = ComponentProps<"div"> &
  VariantProps<typeof metricCardVariants> & {
    label: string;
    value: number;
    prefix?: string;
    suffix?: string;
    decimals?: number;
    trend?: {
      value: number;
      label?: string;
    };
    sparkline?: number[];
    footer?: ReactNode;
  };

export function MetricCard({
  className,
  size,
  label,
  value,
  prefix,
  suffix,
  decimals = 0,
  trend,
  sparkline,
  footer,
  ...props
}: MetricCardProps) {
  return (
    <div
      data-slot="metric-card"
      className={twMerge(metricCardVariants({ size }), className)}
      {...props}
    >
      <div className="px-4 py-2 ">
        <motion.span
          {...fadeUp(0)}
          className="text-[11px] font-medium uppercase tracking-widest text-muted-foreground"
        >
          {label}
        </motion.span>
      </div>

      <div className="mx-2 mb-2 overflow-hidden rounded-xl bg-card">
        <div className="space-y-3 p-4 pb-2">
          <div className="flex items-baseline justify-between gap-1.5">
            <AnimatedNumber
              value={value}
              prefix={prefix}
              suffix={suffix}
              decimals={decimals}
            />

            {trend && <TrendBadge value={trend.value} label={trend.label} />}
          </div>
        </div>

        {sparkline && sparkline.length > 1 && (
          <Sparkline data={sparkline} trend={trend?.value} />
        )}
      </div>
    </div>
  );
}

type AnimatedNumberProps = {
  value: number;
  prefix?: string;
  suffix?: string;
  decimals?: number;
};

function AnimatedNumber({
  value,
  prefix,
  suffix,
  decimals = 0,
}: AnimatedNumberProps) {
  const motionValue = useMotionValue(0);
  const spring = useSpring(motionValue, {
    stiffness: 80,
    damping: 20,
    mass: 1,
  });
  const display = useTransform(spring, (v) => {
    const formatted = v.toLocaleString("pt-BR", {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    });
    return `${prefix ?? ""}${formatted}${suffix ?? ""}`;
  });

  useEffect(() => {
    motionValue.set(value);
  }, [value, motionValue]);

  return (
    <motion.span
      {...fadeUp(0.08)}
      className="text-xl font-semibold leading-none tracking-[-0.03em]"
    >
      <motion.span>{display}</motion.span>
    </motion.span>
  );
}

type TrendBadgeProps = {
  value: number;
  label?: string;
};

function TrendBadge({ value, label }: TrendBadgeProps) {
  const isPositive = value > 0;
  const isNeutral = value === 0;

  const Icon = isNeutral ? Minus : isPositive ? ArrowUp : ArrowDown;

  return (
    <motion.div
      initial={{ opacity: 0, scale: 0.8, x: -4 }}
      animate={{ opacity: 1, scale: 1, x: 0 }}
      transition={{
        type: "spring",
        stiffness: 400,
        damping: 22,
        delay: 0.5,
      }}
      className={twMerge(
        "ml-1 flex items-center gap-0.5 rounded-full px-2 ",
        "text-[11px] font-medium",
        isPositive && "bg-chart-2/10 text-chart-2",
        !isPositive && !isNeutral && "bg-destructive/10 text-destructive",
        isNeutral && "bg-muted text-muted-foreground",
      )}
    >
      <Icon className="size-3" strokeWidth={2.5} />
      <span>
        {isPositive ? "+" : ""}
        {value}%
      </span>
      {label && (
        <span className="ml-0.5 text-[10px] text-muted-foreground/80">
          {label}
        </span>
      )}
    </motion.div>
  );
}

type SparklineProps = {
  data: number[];
  trend?: number;
};

function Sparkline({ data, trend = 0 }: SparklineProps) {
  const width = 320;
  const height = 64;
  const padding = 0;

  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;

  const points = data.map((v, i) => {
    const x = padding + (i / (data.length - 1)) * (width - padding * 2);
    const y = height - padding - ((v - min) / range) * (height - padding * 2);
    return { x, y };
  });

  const pathD = points
    .map((p, i) => {
      if (i === 0) return `M ${p.x} ${p.y}`;
      const prev = points[i - 1];
      const cpx1 = prev.x + (p.x - prev.x) * 0.4;
      const cpx2 = prev.x + (p.x - prev.x) * 0.6;
      return `C ${cpx1} ${prev.y} ${cpx2} ${p.y} ${p.x} ${p.y}`;
    })
    .join(" ");

  const areaD = `${pathD} L ${points[points.length - 1].x} ${height} L ${points[0].x} ${height} Z`;

  const strokeColor =
    trend > 0
      ? "var(--chart-2)"
      : trend < 0
        ? "var(--destructive)"
        : "var(--muted-foreground)";

  const gradientId = `sparkline-gradient-${Math.random().toString(36).slice(2, 8)}`;

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ delay: 0.35, duration: 0.5 }}
    >
      <svg
        viewBox={`0 0 ${width} ${height}`}
        className="w-full"
        preserveAspectRatio="none"
      >
        <title>Gráfico sparkline de tendência</title>
        <defs>
          <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={strokeColor} stopOpacity={0.12} />
            <stop offset="100%" stopColor={strokeColor} stopOpacity={0} />
          </linearGradient>
        </defs>

        <motion.path
          d={areaD}
          fill={`url(#${gradientId})`}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.6, duration: 0.4 }}
        />

        <motion.path
          d={pathD}
          fill="none"
          stroke={strokeColor}
          strokeWidth={2}
          strokeLinecap="round"
          strokeLinejoin="round"
          initial={{ pathLength: 0 }}
          animate={{ pathLength: 1 }}
          transition={{
            duration: 1.2,
            ease: [0.16, 1, 0.3, 1],
            delay: 0.3,
          }}
        />

        <motion.circle
          cx={points[points.length - 1].x}
          cy={points[points.length - 1].y}
          r={3}
          fill={strokeColor}
          initial={{ scale: 0, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          transition={{ delay: 1.4, type: "spring", stiffness: 400 }}
        />
      </svg>
    </motion.div>
  );
}

