"use client";

import { AnimatePresence, motion } from "framer-motion";
import { type ComponentProps, useCallback, useState } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

export const feedbackCardVariants = tv({
  base: [
    "w-full overflow-hidden rounded-[20px] border border-border",
    "bg-secondary text-foreground",
  ],
  variants: {
    size: {
      sm: "max-w-[320px]",
      md: "max-w-[380px]",
      lg: "max-w-[440px]",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type FeedbackOption = {
  value: string;
  emoji: string;
  label: string;
};

export type FeedbackCardProps = ComponentProps<"div"> &
  VariantProps<typeof feedbackCardVariants> & {
    title?: string;
    subtitle?: string;
    options?: FeedbackOption[];
    onSubmit?: (data: { rating: FeedbackOption; message: string }) => void;
    successTitle?: string;
    successDescription?: string;
  };

const defaultOptions: FeedbackOption[] = [
  { value: "terrible", emoji: "😡", label: "Péssimo" },
  { value: "bad", emoji: "😕", label: "Ruim" },
  { value: "okay", emoji: "😐", label: "Ok" },
  { value: "good", emoji: "😊", label: "Bom" },
  { value: "amazing", emoji: "🤩", label: "Incrível" },
];

type Step = "rating" | "message" | "success";

function AnimatedCheck() {
  return (
    <motion.div
      initial={{ scale: 0, opacity: 0 }}
      animate={{ scale: 1, opacity: 1 }}
      transition={{
        type: "spring",
        stiffness: 300,
        damping: 20,
        delay: 0.15,
      }}
      className="flex size-14 items-center justify-center rounded-full bg-chart-2/15"
    >
      <svg
        viewBox="0 0 24 24"
        fill="none"
        className="size-7 text-chart-2"
        stroke="currentColor"
        strokeWidth={2.5}
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <title>Sucesso</title>
        <motion.path
          d="M5 13l4 4L19 7"
          initial={{ pathLength: 0 }}
          animate={{ pathLength: 1 }}
          transition={{
            duration: 0.5,
            ease: [0.65, 0, 0.35, 1],
            delay: 0.35,
          }}
        />
      </svg>
    </motion.div>
  );
}

type EmojiButtonProps = {
  option: FeedbackOption;
  index: number;
  isSelected: boolean;
  onSelect: (option: FeedbackOption) => void;
};

function EmojiButton({
  option,
  index,
  isSelected,
  onSelect,
}: EmojiButtonProps) {
  return (
    <motion.button
      type="button"
      onClick={() => onSelect(option)}
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{
        delay: index * 0.06 + 0.1,
        duration: 0.3,
        ease: [0.25, 0.46, 0.45, 0.94],
      }}
