    />
  );
}

export const spotlightCardContentVariants = tv({
  base: ["px-5 py-3"],
});

export type SpotlightCardContentProps = ComponentProps<"div"> &
  VariantProps<typeof spotlightCardContentVariants>;

export function SpotlightCardContent({
